// Solve a single cell with the C code generated by `gotranx ode2c`.
//
// Usage: main <output.csv>
//
// The generated header (model.h) provides everything used below: the number of states and
// monitored values, the initial values, index lookups by name, monitor_values and the
// numerical scheme (here generalized_rush_larsen).
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "model.h"

static int lookup(int index, const char *name)
{
    if (index < 0) {
        fprintf(stderr, "No variable named '%s' in the model\n", name);
        exit(1);
    }
    return index;
}

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <output.csv>\n", argv[0]);
        return 1;
    }

    const double dt = 0.01;     // ms
    const double t_end = 2000.0;  // ms, two beats with the default 1000 ms stimulus period
    const int save_every = 10;  // save every 0.1 ms

    double *parameters = malloc(NUM_PARAMS * sizeof(double));
    double *states = malloc(NUM_STATES * sizeof(double));
    double *values = malloc(NUM_STATES * sizeof(double));
    double *monitors = malloc(NUM_MONITORED * sizeof(double));
    init_parameter_values(parameters);
    init_state_values(states);

    // Look the variables up by name, so the program does not depend on their order
    const int v = lookup(state_index("v"), "v");
    const int cai = lookup(state_index("cai"), "cai");
    const int INa = lookup(monitor_index("INa"), "INa");

    FILE *out = fopen(argv[1], "w");
    if (out == NULL) {
        fprintf(stderr, "Could not open %s\n", argv[1]);
        return 1;
    }
    fprintf(out, "t,v,cai,INa\n");

    const int num_steps = (int)(t_end / dt);
    for (int step = 0; step <= num_steps; step++) {
        const double t = step * dt;
        if (step % save_every == 0) {
            monitor_values(t, states, parameters, monitors);
            fprintf(out, "%g,%.10g,%.10g,%.10g\n", t, states[v], states[cai], monitors[INa]);
        }
        // The scheme writes the states at t + dt into `values`
        generalized_rush_larsen(states, t, dt, parameters, values);
        memcpy(states, values, NUM_STATES * sizeof(double));
    }

    fclose(out);
    free(parameters);
    free(states);
    free(values);
    free(monitors);
    return 0;
}
